create index if not exists integration_events_pending_idx on public.integration_events(created_at) where status in ('pending','retry','processing'); create index if not exists integration_events_funnel_time_idx on public.integration_events(funnel_id,created_at desc); create index if not exists integration_events_external_idx on public.integration_events(user_id,external_id) where external_id is not null; create index if not exists integration_events_event_key_idx on public.integration_events(user_id,event_key) where event_key is not null;